// 1. 调用 Python 爬虫抓取 Amazon 页面
const { execSync } = require('child_process');
const body = $input.first().json.body;
const url = body.url;

if (!url) {
  throw new Error('缺少 url 参数');
}

let result;
try {
  const cmd = `python3 /Users/panjinlong/Documents/agent-master/n8n-automation/scripts/amazon_scraper.py "${url.replace(/"/g, '\\"')}"`;
  const stdout = execSync(cmd, { timeout: 45000, encoding: 'utf8' });
  result = JSON.parse(stdout.trim());
} catch (e) {
  throw new Error('爬取失败: ' + e.message.substring(0, 200));
}

if (result.error) {
  throw new Error('爬虫返回错误: ' + result.error);
}

// 格式化 bullets
const bulletsText = (result.bullets || []).map((b, i) => `${i+1}. ${b}`).join('\n');

return [{
  json: {
    // 从 webhook body 读取记录定位信息
    app_token: body.app_token,
    table_id: body.table_id,
    record_id: body.record_id,
    sku_table_id: body.sku_table_id || 'tblEOeeD4HARuHuI',
    // 爬取结果
    asin: result.asin || '',
    title: result.title || '',
    brand: result.brand || '',
    bullets_text: bulletsText,
    variants: result.variants || [],
    size_chart: result.size_chart || '',
    source_url: url
  }
}];

// 2. 获取 Feishu tenant_access_token
const https = require('https');

const APP_ID = 'cli_a9460d39a5395bdd';
const APP_SECRET = 'VL57clXcR2kFndvW4Pcj86A3hE6EOSiQ';

const tokenData = await new Promise((resolve, reject) => {
  const body = JSON.stringify({ app_id: APP_ID, app_secret: APP_SECRET });
  const req = https.request({
    hostname: 'open.feishu.cn',
    path: '/open-apis/auth/v3/tenant_access_token/internal',
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(body) }
  }, (res) => {
    let data = '';
    res.on('data', chunk => data += chunk);
    res.on('end', () => resolve(JSON.parse(data)));
  });
  req.on('error', reject);
  req.write(body);
  req.end();
});

if (tokenData.code !== 0) {
  throw new Error('获取飞书Token失败: ' + JSON.stringify(tokenData));
}

const prev = $input.first().json;
return [{ json: { ...prev, feishu_token: tokenData.tenant_access_token } }];

// 3. 更新 ASIN 主表记录（回填爬取数据）
const https = require('https');
const d = $input.first().json;

const fields = {
  'ASIN': d.asin,
  '产品名称': d.title,
  '现有标题': d.title,
  'Bullet原版(1-5)': d.bullets_text,
  '任务状态': '文案生成中'
};

if (d.size_chart) fields['尺码数据'] = d.size_chart;

const payload = JSON.stringify({ fields });
const token = d.feishu_token;
const url = `/open-apis/bitable/v1/apps/${d.app_token}/tables/${d.table_id}/records/${d.record_id}`;

const resp = await new Promise((resolve, reject) => {
  const req = https.request({
    hostname: 'open.feishu.cn',
    path: url,
    method: 'PUT',
    headers: {
      'Content-Type': 'application/json',
      'Authorization': `Bearer ${token}`,
      'Content-Length': Buffer.byteLength(payload)
    }
  }, (res) => {
    let data = '';
    res.on('data', chunk => data += chunk);
    res.on('end', () => resolve(JSON.parse(data)));
  });
  req.on('error', reject);
  req.write(payload);
  req.end();
});

if (resp.code !== 0) {
  throw new Error('回填主表失败: ' + JSON.stringify(resp).substring(0, 200));
}

return [{ json: { ...d, main_table_updated: true } }];

// 4. 在 SKU 变体表批量创建变体记录
const https = require('https');
const d = $input.first().json;

const variants = d.variants || [];
if (variants.length === 0) {
  return [{ json: { ...d, skus_created: 0 } }];
}

const token = d.feishu_token;
const asin = d.asin;
const skuTable = d.sku_table_id;
const appToken = d.app_token;

// Build batch records
const records = variants.slice(0, 20).map(v => ({
  fields: {
    'SKU ID': `${asin}-${v}`,
    '变体名称': v
  }
}));

// Batch create via Feishu API
const batchUrl = `/open-apis/bitable/v1/apps/${appToken}/tables/${skuTable}/records/batch_create`;
const payload = JSON.stringify({ records });

const resp = await new Promise((resolve, reject) => {
  const req = https.request({
    hostname: 'open.feishu.cn',
    path: batchUrl,
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Authorization': `Bearer ${token}`,
      'Content-Length': Buffer.byteLength(payload)
    }
  }, (res) => {
    let data = '';
    res.on('data', chunk => data += chunk);
    res.on('end', () => resolve(JSON.parse(data)));
  });
  req.on('error', reject);
  req.write(payload);
  req.end();
});

const skusCreated = resp.data?.records?.length || 0;
return [{ json: { ...d, skus_created: skusCreated, sku_resp_code: resp.code } }];

// 5. 更新主表状态为「待审核」
const https = require('https');
const d = $input.first().json;

const payload = JSON.stringify({ fields: { '任务状态': '待审核' } });
const token = d.feishu_token;
const url = `/open-apis/bitable/v1/apps/${d.app_token}/tables/${d.table_id}/records/${d.record_id}`;

await new Promise((resolve, reject) => {
  const req = https.request({
    hostname: 'open.feishu.cn',
    path: url,
    method: 'PUT',
    headers: {
      'Content-Type': 'application/json',
      'Authorization': `Bearer ${token}`,
      'Content-Length': Buffer.byteLength(payload)
    }
  }, (res) => {
    let data = '';
    res.on('data', chunk => data += chunk);
    res.on('end', () => resolve(JSON.parse(data)));
  });
  req.on('error', reject);
  req.write(payload);
  req.end();
});

return [{ json: { ...d, status_updated: true } }];
